<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { useClinicContextStore } from '../../stores/clinicContext';import { useDoctorStore } from '../../stores/doctors';import { doctorService } from '../../services/doctors';import FormErrors from '../ui/FormErrors.vue';
const props=defineProps({doctor:Object});const context=useClinicContextStore(),store=useDoctorStore(),router=useRouter();
const fields=[['first_name','First name','text',true],['middle_name','Middle name','text'],['last_name','Last name','text',true],['phone','Phone','tel'],['email','Email','email']];
const form=reactive({...Object.fromEntries(fields.map(([key])=>[key,props.doctor?.[key]||''])),gender:props.doctor?.gender||'',license_number:props.doctor?.license_number||'',qualification:props.doctor?.qualification||'',consultation_fee:props.doctor?.consultation_fee??'',notes:props.doctor?.notes||'',specialty_ids:props.doctor?.specialties.map(s=>s.id)||[],primary_branch_id:props.doctor?.primary_branch_id||context.data.branch.id,branch_ids:props.doctor?.branches.map(b=>b.id)||[],status:props.doctor?.status||'active',availability_status:props.doctor?.availability_status||'available',account_mode:'none',user_id:'',account_email:'',password:'',password_confirmation:'',account_permissions:store.options.account_permissions.slice()});
const busy=ref(false),error=ref(null),duplicates=ref(null),specialty=ref('');
async function addSpecialty(){error.value=null;try{const {data}=await doctorService.specialty(specialty.value);store.options.specialties.push(data.data);form.specialty_ids.push(data.data.id);specialty.value='';}catch(e){error.value=e;}}
async function save(confirm=false){busy.value=true;error.value=null;duplicates.value=null;const data={...form,confirm_duplicate:confirm};if(data.account_mode==='none'){delete data.user_id;delete data.account_email;delete data.password;delete data.password_confirmation;delete data.account_permissions;}if(data.account_mode==='existing'){delete data.account_email;delete data.password;delete data.password_confirmation;delete data.account_permissions;}try{const response=await doctorService.save(props.doctor?.id,data);form.password='';form.password_confirmation='';store.notice=props.doctor?'Doctor updated successfully.':'Doctor created successfully.';await router.push(`/app/doctors/${response.data.data.id}`);}catch(e){if(e.response?.status===409 && 'duplicates' in e.response.data)duplicates.value=e.response.data.duplicates;else error.value=e;}finally{busy.value=false;}}
</script>
<template><form class="patient-form" @submit.prevent="save()"><FormErrors :error="error"/><section v-if="duplicates" class="clinic-panel border-amber-300 bg-amber-50" role="alert"><h2 class="font-bold">A similar clinician profile already exists.</h2><div v-for="d in duplicates" :key="d.id" class="patient-document-row"><span>{{d.full_name}} · {{d.doctor_number}}</span><RouterLink class="btn-secondary" :to="`/app/doctors/${d.id}`">View profile</RouterLink></div><button class="btn mt-4" type="button" :disabled="busy" @click="save(true)">Continue Creating Doctor</button></section>
<section class="clinic-panel"><div class="patient-section-heading"><span>1</span><h2>Personal information</h2></div><div class="patient-form-grid"><label v-for="[key,label,type,required] in fields" :key="key" class="field">{{label}}{{required?' *':''}}<input v-model="form[key]" :type="type" :required="required" :maxlength="key==='phone'?40:key==='email'?255:100"><span v-if="error?.response?.data.errors?.[key]" class="text-xs text-rose-700">{{error.response.data.errors[key][0]}}</span></label><label class="field">Gender<select v-model="form.gender"><option value="">Not specified</option><option value="male">Male</option><option value="female">Female</option></select></label></div></section>
<section class="clinic-panel"><div class="patient-section-heading"><span>2</span><h2>Professional information</h2></div><div class="patient-form-grid"><fieldset class="col-span-full"><legend class="field mb-3">Specialties *</legend><div class="doctor-checkboxes"><label v-for="s in store.options.specialties" :key="s.id"><input v-model="form.specialty_ids" type="checkbox" :value="s.id">{{s.name}}</label></div><p v-if="!store.options.specialties.length" class="text-sm text-slate-500">Add your clinic’s first specialty below.</p><div v-if="context.can('doctors.specialties.manage')" class="mt-4 flex flex-wrap gap-3"><input v-model="specialty" aria-label="New specialty" placeholder="New specialty name" class="filter-input max-w-sm" maxlength="120"><button class="btn-secondary" type="button" :disabled="!specialty.trim()" @click="addSpecialty">Add Specialty</button></div><p v-if="error?.response?.data.errors?.specialty_ids" class="mt-2 text-rose-700 text-xs">{{error.response.data.errors.specialty_ids[0]}}</p></fieldset><label class="field">License number<input v-model="form.license_number" maxlength="100"></label><label class="field">Qualification<input v-model="form.qualification" maxlength="255"></label><label class="field">Consultation fee ({{context.data.plan?.currency || 'USD'}})<input v-model="form.consultation_fee" type="number" min="0" max="9999999999.99" step="0.01"></label><label class="field col-span-full">Notes<textarea v-model="form.notes" rows="3" maxlength="5000"></textarea></label></div></section>
<section class="clinic-panel"><div class="patient-section-heading"><span>3</span><h2>Branch assignment</h2></div><div class="patient-form-grid"><label class="field">Primary branch *<select v-model="form.primary_branch_id" required><option v-for="b in store.options.branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><fieldset class="col-span-full"><legend class="field mb-3">Additional branches</legend><div class="doctor-checkboxes"><label v-for="b in store.options.branches.filter(b=>b.id!==Number(form.primary_branch_id))" :key="b.id"><input v-model="form.branch_ids" type="checkbox" :value="b.id">{{b.name}}</label></div><p v-if="store.options.branches.length===1" class="text-sm text-slate-500">This clinic has one accessible branch.</p></fieldset></div></section>
<section v-if="context.can('staff.manage')" class="clinic-panel"><div class="patient-section-heading"><span>4</span><h2>User account</h2></div><p v-if="doctor?.user" class="mt-4 text-slate-600">Linked to {{doctor.user.name}} ({{doctor.user.email}}). Account access is managed separately.</p><template v-else><label class="field mt-5 max-w-sm">Account setup<select v-model="form.account_mode"><option value="none">No login account</option><option value="existing">Link existing clinic user</option><option value="create">Create user account</option></select></label><label v-if="form.account_mode==='existing'" class="field mt-4">Existing user<select v-model="form.user_id" required><option value="">Select a clinic user</option><option v-for="u in store.options.users" :key="u.id" :value="u.id">{{u.name}} — {{u.email}}</option></select></label><div v-if="form.account_mode==='create'" class="patient-form-grid"><label class="field">Account email *<input v-model="form.account_email" type="email" required autocomplete="off"></label><label class="field">Temporary password *<input v-model="form.password" type="password" minlength="12" required autocomplete="new-password"></label><label class="field">Confirm password *<input v-model="form.password_confirmation" type="password" minlength="12" required autocomplete="new-password"></label><p class="hint col-span-full">Use at least 12 characters, uppercase and lowercase letters, and a number. Role: Doctor / Clinician. The account receives access only to assigned branches.</p><details class="col-span-full"><summary class="cursor-pointer text-sm font-semibold text-teal-700">Account permissions</summary><div class="doctor-checkboxes mt-4"><label v-for="permission in store.options.account_permissions" :key="permission"><input v-model="form.account_permissions" type="checkbox" :value="permission">{{permission.replaceAll('.',' ').replaceAll('_',' ')}}</label></div></details></div></template></section>
<section class="clinic-panel"><div class="patient-section-heading"><span>5</span><h2>Status &amp; availability</h2></div><div class="patient-form-grid"><label v-if="!doctor" class="field">Status<select v-model="form.status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label class="field">Availability<select v-model="form.availability_status"><option v-for="v in ['available','in_consultation','unavailable','on_leave']" :key="v" :value="v">{{v.replaceAll('_',' ')}}</option></select></label></div><p class="hint mt-4">Configure working hours and dated leave on the Schedule tab after saving.</p></section><div class="sticky-actions"><RouterLink class="btn-secondary" to="/app/doctors">Cancel</RouterLink><button class="btn" :disabled="busy">{{busy?'Saving...':doctor?'Save Changes':'Create Doctor'}}</button></div></form></template>
